seen=set()
def walk(cat,d=0):
    if cat in seen or d>3: return
    seen.add(cat)
    r=q(action='query',list='categorymembers',cmtitle=cat,cmlimit=500)
    for m in r['query']['categorymembers']:
        if m['ns']==14: print('  '*d+'[cat]',m['title']); walk(m['title'],d+1)
        elif m['ns']==0: print('  '*d+m['title'])
walk('Category:Manichaean art')
EOF

